const { S3Client, ListObjectsV2Command, GetObjectCommand } = require('@aws-sdk/client-s3');
const { getUserFromEvent, createResponse, createErrorResponse } = require('./authUtils');

const s3Client = new S3Client({});

exports.main = async (event) => {
  try {
    // Require authentication
    const user = getUserFromEvent(event);
    if (!user) {
      return createErrorResponse(401, 'Authentication required');
    }

    // List all session metadata files
    const listCommand = new ListObjectsV2Command({
      Bucket: process.env.SESSION_BUCKET_NAME,
      Prefix: 'metadata/',
    });

    const listResponse = await s3Client.send(listCommand);
    const userSessions = [];

    if (listResponse.Contents) {
      // Get metadata for each session and filter by owner
      for (const object of listResponse.Contents) {
        try {
          const getCommand = new GetObjectCommand({
            Bucket: process.env.SESSION_BUCKET_NAME,
            Key: object.Key,
          });

          const response = await s3Client.send(getCommand);
          const body = await response.Body?.transformToString();
          const metadata = JSON.parse(body);

          // Include session if user is the owner
          if (metadata.ownerId && metadata.ownerId.toString() === user.userId.toString()) {
            userSessions.push({
              id: metadata.id,
              createdAt: metadata.createdAt,
              isPrivate: metadata.isPrivate,
              // Add basic stats if available
              lastModified: object.LastModified,
              size: object.Size,
            });
          }
        } catch (error) {
          console.error(`Error processing session metadata ${object.Key}:`, error);
          // Continue processing other sessions
        }
      }
    }

    // Sort by creation date (newest first)
    userSessions.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));

    return createResponse(200, {
      sessions: userSessions,
      total: userSessions.length,
      user: {
        id: user.userId,
        username: user.username,
      },
    });

  } catch (error) {
    console.error('Error in getUserSessions:', error);
    return createErrorResponse(500, 'Error retrieving user sessions');
  }
};

